    region customers (
        name: Customers
        type: classicReport
        source {
            location: localDatabase
            tableName: OEHR_CUSTOMERS
        }
        layout {
            sequence: 20
            slot: body
        }
        appearance {
            template: @standard
            templateOptions: [
                #DEFAULT#
                t-Region--noPadding
            ]
        }
        reportLayout {
            numberOfRows: 50
        }
        componentAppearance {
            template: @standard
            templateOptions: [
                #DEFAULT#
                t-Report--stretch
                t-Report--staticRowColors
                t-Report--rowHighlight
                t-Report--inline
                t-Report--hideNoPagination
            ]
        }
        performance {
            maxRowsToProcess: 100000
        }
        messages {
            whenNoDataFound: no data found
        }

        column ACCOUNT_MGR_ID (
            reportColumnQueryId: 14
            derivedColumn: N
            type: hidden
            layout {
                sequence: 14
            }
        )

        column CITY (
            reportColumnQueryId: 6
            derivedColumn: N
            heading {
                heading: City
            }
            layout {
                sequence: 6
            }
        )

        column COUNTRY_ID (
            reportColumnQueryId: 8
            derivedColumn: N
            heading {
                heading: Country ID
            }
            layout {
                sequence: 8
            }
        )

        column CREDIT_LIMIT (
            reportColumnQueryId: 12
            derivedColumn: N
